using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// X86 转译器 (16/32 位)
    /// </summary>
    public class TranslatorX86 : Translator32bit
    {
        public override string ARCH_NAME => "X86";
        public string Mode { get; set; } = "32";

        protected override string[] ContextRegNames() => new[] { "eax", "ebx", "ecx", "edx", "esi", "edi", "ebp" };
        protected override string NativeInt(int vector) => $"int {vector}";
        protected override string NativeIret() => "iret";
        protected override string NativeCli() => "cli";
        protected override string NativeSti() => "sti";
        protected override void EmitCLC() => Emit("        clc");
        protected override void EmitSTC() => Emit("        stc");

        private Dictionary<int, string> REGISTER_MAP => Mode == "16"
            ? new Dictionary<int, string>
            {
                { 0, "AX" }, { 1, "BX" }, { 2, "CX" }, { 3, "DX" },
                { 4, "SI" }, { 5, "DI" }, { 6, "BP" }, { 7, "SP" }
            }
            : new Dictionary<int, string>
            {
                { 0, "EAX" }, { 1, "EBX" }, { 2, "ECX" }, { 3, "EDX" },
                { 4, "ESI" }, { 5, "EDI" }, { 6, "EBP" }, { 7, "ESP" }
            };

        public TranslatorX86(VmlProgram vmlProgram, string mode = "32") : base(vmlProgram)
        {
            Mode = mode;
        }

        protected override void EmitHeader()
        {
            string bits = Mode;
            Emit($"; X86 Assembly ({bits}-bit) - Translated from VML");
            Emit("; Generated by VML Translator");
            Emit("");
            Emit($"bits {bits}");
            Emit("org 0x7C00");
            Emit("");
            Emit("section .text");
            Emit("    global _start");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("section .data");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is string strValue)
                    {
                        // NASM doesn't handle \n escapes in '' strings by default
                        // Emit as byte sequence to be safe
                        var bytes = new List<string>();
                        foreach (char c in strValue)
                        {
                            if (c == '\n') bytes.Add("0x0A");
                            else if (c == '\r') bytes.Add("0x0D");
                            else if (c == '\t') bytes.Add("0x09");
                            else if (c == '\'') bytes.Add("0x27");
                            else if (c == '\\') bytes.Add("0x5C");
                            else if (c < 32 || c > 126)
                                bytes.Add($"0x{(byte)c:X2}");
                            else
                                bytes.Add($"'{c}'");
                        }
                        Emit($"{name}: db {string.Join(", ", bytes)}, 0");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        string vals = string.Join(", ", listValue);
                        Emit($"{name}: db {vals}");
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"{name}: dd {intValue}");
                    }
                }
            }
        }

        protected override void EmitCode()
        {
            Emit("");
            Emit("section .text");
            Emit("_start:");

            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                {
                    Emit($"{instr.Label}:");
                }
                NormalizeAndTranslate(instr);
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    TranslateMul(instr);
                    break;
                case OpCode.DIV:
                    TranslateDiv(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.PUSH:
                    Emit($"    push {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.POP:
                    Emit($"    pop {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"    jmp {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                    Emit($"    jz {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                    Emit($"    jnz {instr.Operands[0].Value}");
                    break;
                case OpCode.JE:
                    Emit($"    je {instr.Operands[0].Value}");
                    break;
                case OpCode.JNE:
                    Emit($"    jne {instr.Operands[0].Value}");
                    break;
                case OpCode.JL:
                    Emit($"    jl {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"    jle {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"    jg {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"    jge {instr.Operands[0].Value}");
                    break;
                case OpCode.CALL:
                    Emit($"    call {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("    ret");
                    break;
                case OpCode.HALT:
                    TranslateHalt();
                    break;
                case OpCode.NOP:
                    Emit("    nop");
                    break;
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit("    mov eax, " + GetOperandValue(instr.Operands[0]));
                    Emit("    int 0");
                    break;
                case OpCode.CATCH:
                    Emit($"    mov gs:0, {instr.Operands[0].Value}");
                    break;
                case OpCode.ENDCATCH:
                    Emit("    mov gs:0, 0");
                    break;

                // 浮点运算指令 (SSE2)
                case OpCode.FADD:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    addss xmm0, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, xmm0");
                    break;
                case OpCode.FSUB:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    subss xmm0, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, xmm0");
                    break;
                case OpCode.FMUL:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    mulss xmm0, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, xmm0");
                    break;
                case OpCode.FDIV:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    divss xmm0, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, xmm0");
                    break;
                case OpCode.FNEG:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[0])}");
                    Emit("    xorps xmm1, xmm1");
                    Emit("    subss xmm1, xmm0");
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, xmm1");
                    break;
                case OpCode.FCMP:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[0])}");
                    Emit($"    ucomiss xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit("    jp .unordered");
                    Emit("    je .fequal");
                    Emit("    jb .fless");
                    Emit("    ja .fgreater");
                    break;

                // 浮点类型转换
                case OpCode.I2F:
                    Emit($"    mov eax, {GetOperandValue(instr.Operands[1])}");
                    Emit("    cvtsi2ss xmm0, eax");
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, xmm0");
                    break;
                case OpCode.F2I:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit("    cvttss2si eax, xmm0");
                    Emit($"    mov {GetOperandValue(instr.Operands[0])}, eax");
                    break;
                case OpCode.F2D:
                    Emit($"    movss xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit("    cvtss2sd xmm0, xmm0");
                    Emit($"    movsd {GetOperandValue(instr.Operands[0])}, xmm0");
                    break;
                case OpCode.D2F:
                    Emit($"    movsd xmm0, {GetOperandValue(instr.Operands[1])}");
                    Emit("    cvtsd2ss xmm0, xmm0");
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, xmm0");
                    break;

                // 浮点数据传输
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    Emit("    sub esp, 4");
                    Emit($"    movss [esp], {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.FPOP:
                    Emit($"    movss {GetOperandValue(instr.Operands[0])}, [esp]");
                    Emit("    add esp, 4");
                    break;

                // --- 缺失的指令补全 ---

                // 位运算指令
                case OpCode.AND:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    and {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                        Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}");
                    }
                    else
                    {
                        Emit($"    mov EAX, {GetOperandValue(instr.Operands[1])}");
                        Emit($"    and EAX, {GetOperandValue(instr.Operands[2])}");
                        Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, EAX");
                    }
                    break;
                case OpCode.OR:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    or {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                        Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}");
                    }
                    else
                    {
                        Emit($"    mov EAX, {GetOperandValue(instr.Operands[1])}");
                        Emit($"    or EAX, {GetOperandValue(instr.Operands[2])}");
                        Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, EAX");
                    }
                    break;
                case OpCode.XOR:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    xor {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                        Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}");
                    }
                    else
                    {
                        Emit($"    mov EAX, {GetOperandValue(instr.Operands[1])}");
                        Emit($"    xor EAX, {GetOperandValue(instr.Operands[2])}");
                        Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, EAX");
                    }
                    break;
                case OpCode.NOT:
                    Emit($"    not {GetOperandValue(instr.Operands[0])}");
                    break;

                // 移位指令
                case OpCode.SHL:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    mov ECX, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    mov ECX, {GetOperandValue(instr.Operands[2])}");
                    }
                    Emit($"    mov EAX, {GetOperandValue(instr.Operands[1])}");
                    Emit("    shl EAX, CL");
                    Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, EAX");
                    break;
                case OpCode.SHR:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    mov ECX, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    mov ECX, {GetOperandValue(instr.Operands[2])}");
                    }
                    Emit($"    mov EAX, {GetOperandValue(instr.Operands[1])}");
                    Emit("    shr EAX, CL");
                    Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, EAX");
                    break;

                // 单目算术指令
                case OpCode.INC:
                    Emit($"    inc {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.DEC:
                    Emit($"    dec {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.NEG:
                    Emit($"    neg {GetOperandValue(instr.Operands[0])}");
                    break;

                // 模运算: MOD = A % B (x86 idiv)
                case OpCode.MOD:
                    Emit($"    mov EAX, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    mov ECX, {GetOperandValue(instr.Operands[2])}");
                    Emit("    cdq");                  // sign-extend EAX → EDX:EAX
                    Emit("    idiv ECX");             // EAX=商, EDX=余数
                    Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, EDX");
                    break;

                // TEST: 与运算并设置标志位
                case OpCode.TEST:
                    if (instr.Operands[1].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    test {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    }
                    else
                    {
                        Emit($"    test {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}");
                    }
                    break;

                // 函数返回（带值）
                // case OpCode.RET_VAL:
                //     Emit($"    mov EAX, {GetOperandValue(instr.Operands[0])}");
                //     Emit("    ret");
                //     break;

                // 标签定义
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;

                // 系统调用 (x86 实模式 BIOS int 0x10 输出)
                case OpCode.SYSCALL:
                    {
                        string num = GetOperandValue(instr.Operands[0]);
                        if (num == "1")
                        {   // OutputString: loop through chars, AX=string addr
                            Emit("    push si");
                            Emit("    mov si, ax");
                            Emit("    cld");
                            Emit(".putstr_loop:");
                            Emit("    lodsb");
                            Emit("    or al, al");
                            Emit("    jz .putstr_done");
                            Emit("    mov ah, 0x0E");
                            Emit("    int 0x10");
                            Emit("    jmp .putstr_loop");
                            Emit(".putstr_done:");
                            Emit("    pop si");
                        }
                        else if (num == "4")
                        {   // OutputChar: AL=char, AH=0x0E via INT 0x10
                            Emit("    mov ah, 0x0E");
                            Emit("    int 0x10");
                        }
                        else if (num == "3")
                        {   // Exit: hang
                            Emit("    cli");
                            Emit("    hlt");
                        }
                        else
                            Emit("    int 0x80");
                    }
                    break;

                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 栈帧管理
                case OpCode.ENTER:
                    {
                        int size = int.Parse(instr.Operands[0].Value.ToString());
                        Emit("    push ebp");
                        Emit("    mov ebp, esp");
                        if (size > 0)
                            Emit($"    sub esp, {size}");
                    }
                    break;
                case OpCode.LEAVE:
                    Emit("    leave");
                    break;

                // 标志位控制
                // 地址计算
                                // 调试
                case OpCode.BREAK:
                    Emit("    int 3");
                    break;

                // 8位/16位数据传输
                                                                                case OpCode.MOVEB:
                    {
                        string dstReg = GetOperandValue(instr.Operands[0]);
                        string srcReg = GetOperandValue(instr.Operands[1]);
                        Emit($"    mov {dstReg}, {srcReg}");
                        Emit($"    and {dstReg}, 0xFF");
                    }
                    break;
                case OpCode.MOVEH:
                    {
                        string dstReg = GetOperandValue(instr.Operands[0]);
                        string srcReg = GetOperandValue(instr.Operands[1]);
                        Emit($"    mov {dstReg}, {srcReg}");
                        Emit($"    and {dstReg}, 0xFFFF");
                    }
                    break;
                case OpCode.PUSHB:
                    Emit($"    push {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.PUSHH:
                    Emit($"    push {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.POPB:
                    Emit($"    pop {GetOperandValue(instr.Operands[0])}");
                    Emit($"    and {GetOperandValue(instr.Operands[0])}, 0xFF");
                    break;
                case OpCode.POPH:
                    Emit($"    pop {GetOperandValue(instr.Operands[0])}");
                    Emit($"    and {GetOperandValue(instr.Operands[0])}, 0xFFFF");
                    break;

                case OpCode.ZERO:
                    Emit($"    xor {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.SHLV:
                    Emit($"    mov cl, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    shl {GetOperandValue(instr.Operands[0])}, cl");
                    break;
                case OpCode.SHRV:
                    Emit($"    mov cl, {GetOperandValue(instr.Operands[2])}");
                    Emit($"    shr {GetOperandValue(instr.Operands[0])}, cl");
                    break;
                case OpCode.I2D:
                case OpCode.D2I:
                    Emit($"    ; {instr.Opcode}: int<->double conversion");
                    Emit($"    call __{instr.Opcode.ToString().ToLower()}");
                    break;

                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // ═══════════════════════════════════════════════════════
                // 符号扩展/条件移动/循环移位 (v1.66.28+)
                // ═══════════════════════════════════════════════════════
                case OpCode.SEXTB:
                    Emit($"    movsx {MapRegister((int)instr.Operands[0].Value)}, byte {GetOperandValue(instr.Operands[1])}");
                    break;
                case OpCode.SEXTH:
                    Emit($"    movsx {MapRegister((int)instr.Operands[0].Value)}, word {GetOperandValue(instr.Operands[1])}");
                    break;
                case OpCode.CMOVZ:
                    Emit($"    jnz .cmovz_skip");
                    Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    .cmovz_skip:");
                    break;
                case OpCode.CMOVNZ:
                    Emit($"    jz .cmovnz_skip");
                    Emit($"    mov {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    .cmovnz_skip:");
                    break;
                case OpCode.ROL:
                    Emit($"    rol {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[2])}");
                    break;
                case OpCode.ROR:
                    Emit($"    ror {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[2])}");
                    break;

                default:
                    Emit($"    ; UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string dstReg = GetOperandValue(dst);

            if (src.Type == OperandType.IMMEDIATE)
            {
                Emit($"    mov {dstReg}, {src.Value}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                Emit($"    mov {dstReg}, [{src.Value}]");
            }
            else if (src.Type == OperandType.LABEL)
            {
                Emit($"    mov {dstReg}, {src.Value}");
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string srcReg = GetOperandValue(src);

            if (dst.Type == OperandType.MEMORY)
            {
                Emit($"    mov [{dst.Value}], {srcReg}");
            }
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Val = GetOperandValue(src1);

            Emit($"    mov {dstReg}, {src1Val}");

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    add {dstReg}, {src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    add {dstReg}, {src2Reg}");
            }
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Val = GetOperandValue(src1);

            Emit($"    mov {dstReg}, {src1Val}");

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    sub {dstReg}, {src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    sub {dstReg}, {src2Reg}");
            }
        }

        private void TranslateMul(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    imul {dstReg}, {src1Reg}, {src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    imul {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateDiv(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            // 简化处理：使用 EAX 作为被除数
            string src1Reg = GetOperandValue(src1);
            Emit($"    mov eax, {src1Reg}");

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    mov ebx, {src2.Value}");
                Emit("    xor edx, edx");
                Emit("    idiv ebx");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    mov ebx, {src2Reg}");
                Emit("    xor edx, edx");
                Emit("    idiv ebx");
            }

            Emit($"    mov {GetOperandValue(dst)}, eax");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    cmp {src1Reg}, {src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    cmp {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateHalt()
        {
            // Linux syscall: exit(0)
            if (Mode == "32")
            {
                Emit("    mov eax, 1");
                Emit("    xor ebx, ebx");
                Emit("    int 0x80");
            }
            else
            {
                Emit("    mov eax, 60");
                Emit("    xor edi, edi");
                Emit("    syscall");
            }
        }

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"R{regNum}";
        }

        protected override bool UseImmediateHash => false;
    }
}
